#include <stdio.h>
#include <string.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat a = {"张三", 2};
    struct Cat b;

    b = a;
    b.fish = b.fish + 1;
    strcpy(b.name, "假张三");

    printf("a：%s 处理了 %d 条\n", a.name, a.fish);
    printf("b：%s 处理了 %d 条\n", b.name, b.fish);
    return 0;
}

